                return func(*args, **kwargs)

            if key in cache:
                # Move to end to mark as most recent
                cache.pop(key)
                cache[key] = cache[key]
                hits += 1
                return cache[key]
            else:
                result = func(*args, **kwargs)
                if maxsize > 0:
                    if len(cache) >= maxsize:
                        # Evict most recently used item (last inserted)
                        cache.popitem()
                cache[key] = result
                misses += 1
                return result

        def cache_info():
            return CacheInfo(hits, misses, maxsize, len(cache))

        def cache_clear():
            nonlocal hits, misses
            cache.clear()
            hits = 0
            misses = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        wrapper.__wrapped__ = func
        return wrapper

    return decorator

